        public async Task<IEnumerable<ProductoReadDto>> ListarProductosProceso(Proceso proceso)
        {
            var productos = await _appDbContext.Productos
             .Include(p => p.Categoria)
             .Include(p => p.Notas)
             .Where(p => p.Activo == true && p.proceso == proceso)
